import bpy
import math

COLLECTION_NAME = "R6 Replay Cameras"
CAMERA_NAME = "R6Cam_dyn4mic_P01"
RIG_NAME = "R6Rig_dyn4mic_P01"
BOUNDS_NAME = "R6Bounds_dyn4mic_P01"
